import re
from datetime import datetime


def dedupe_contacts(rows):
    GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
    OPT_OUT_VALUES = {"y", "yes", "true", "1"}
    DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")

    def s(value):
        return "" if value is None else str(value)

    def norm_email(raw):
        e = s(raw)
        m = re.search(r"<([^<>]*)>", e)
        if m:
            e = m.group(1)
        e = e.strip().lower()
        if e.count("@") == 1:
            local, domain = e.split("@")
            if domain in GMAIL_DOMAINS:
                local = local.replace(".", "").split("+")[0]
                domain = "gmail.com"
            e = local + "@" + domain
        # validity
        if e.count("@") != 1:
            return ""
        local, domain = e.split("@")
        if not local:
            return ""
        if "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""
        return e

    def norm_phone(raw):
        p = s(raw)
        m = re.search(r"ext|x|#", p, re.IGNORECASE)
        if m:
            p = p[:m.start()]
        digits = re.sub(r"[^0-9]", "", p)
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def norm_zip(raw):
        z = s(raw).strip()
        m = re.fullmatch(r"([0-9]+)-[0-9]{4}", z)
        if m:
            z = m.group(1)
        if len(z) == 4 and re.fullmatch(r"[0-9]{4}", z):
            z = "0" + z
        if re.fullmatch(r"[0-9]{5}", z):
            return z
        return ""

    def norm_name(raw):
        n = s(raw).strip()
        if n.isupper() or n.islower():
            n = n.title()
        return n

    def parse_updated(raw):
        u = s(raw).strip()
        for fmt in DATE_FORMATS:
            try:
                return datetime.strptime(u, fmt)
            except ValueError:
                continue
        raise ValueError("Unrecognized updated value: %r" % (raw,))

    def split_tags(raw):
        out = []
        for t in re.split(r"[;,]", s(raw)):
            t = t.strip().lower()
            if t:
                out.append(t)
        return out

    # Normalize rows and drop those with no valid email or phone.
    recs = []
    for idx, row in enumerate(rows):
        email = norm_email(row.get("email"))
        phone = norm_phone(row.get("phone"))
        if not email and not phone:
            continue
        source = s(row.get("source")).strip().lower()
        recs.append({
            "idx": idx,
            "first_name": norm_name(row.get("first_name")),
            "last_name": norm_name(row.get("last_name")),
            "zip": norm_zip(row.get("zip")),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": split_tags(row.get("tags")),
            "opted_out": s(row.get("opted_out")).strip().lower() in OPT_OUT_VALUES,
            "updated": parse_updated(row.get("updated")),
        })

    # Union-find over the kept records.
    n = len(recs)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    seen = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email"]:
            keys.append(("e", r["email"]))
        last = r["last_name"].lower()
        if r["phone"] and last:
            keys.append(("p", r["phone"], last))
        for k in keys:
            if k in seen:
                union(i, seen[k])
            else:
                seen[k] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(recs[i])

    def pick(members, field):
        cands = [m for m in members if m[field]]
        if not cands:
            return None
        cands = sorted(cands, key=lambda m: m["idx"])
        cands.sort(key=lambda m: m["updated"], reverse=True)  # stable
        cands.sort(key=lambda m: 0 if m["manual"] else 1)     # stable
        return cands[0]

    ordered = sorted(groups.values(), key=lambda g: min(m["idx"] for m in g))

    result = []
    for members in ordered:
        out = {}
        for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
            best = pick(members, field)
            out[field] = best[field] if best else ""
        tags = set()
        for m in members:
            tags.update(m["tags"])
        out["tags"] = ";".join(sorted(tags))
        out["opted_out"] = "Y" if any(m["opted_out"] for m in members) else "N"
        latest = max(m["updated"] for m in members)
        out["updated"] = "%04d-%02d-%02d" % (latest.year, latest.month, latest.day)
        result.append(out)

    return result
